public class ClueDetailsWorldMapPoint extends WorldMapPoint
{
	private final ClueDetailsPlugin plugin;
	private final BufferedImage clueDetailWorldImage;
	private final Point clueDetailWorldImagePoint;

	public ClueDetailsWorldMapPoint(final WorldPoint worldPoint, ClueDetailsPlugin plugin)
	{
		super(worldPoint, null);

		BufferedImage iconBackground = ImageUtil.loadImageResource(getClass(), "/util/clue_arrow.png");
		clueDetailWorldImage = new BufferedImage(iconBackground.getWidth(), iconBackground.getHeight(), BufferedImage.TYPE_INT_ARGB);

		Graphics graphics = clueDetailWorldImage.getGraphics();
		graphics.drawImage(iconBackground, 0, 0, null);
		graphics.drawImage(plugin.getClueScrollImage(), 0, 0, null);
		clueDetailWorldImagePoint = new Point(
			clueDetailWorldImage.getWidth() / 2,
			clueDetailWorldImage.getHeight());

		this.plugin = plugin;
		this.setSnapToEdge(true);
		this.setJumpOnClick(true);
		this.setName(ClueDetailsPlugin.CLUE_GROUND_TIMER_TARGET);
		this.setImage(clueDetailWorldImage);
		this.setImagePoint(clueDetailWorldImagePoint);
	}

	@Override
	public void onEdgeSnap()
	{
		this.setImage(plugin.getClueScrollImage());
		this.setImagePoint(null);
	}

	@Override
	public void onEdgeUnsnap()
	{
		this.setImage(clueDetailWorldImage);
		this.setImagePoint(clueDetailWorldImagePoint);
	}
}

