package com.cluedetails;

import net.runelite.api.coords.WorldPoint;

public class Zone
{
	private final int x;
	private final int y;

	public Zone(WorldPoint wp)
	{
		x = wp.getX() / 8;
		y = wp.getY() / 8;
	}

	public int maxDistanceTo(Zone zone)
	{
		return Math.max(Math.abs(zone.x - x), Math.abs(zone.y - y));
	}
}

